/* Авторская практика ЕГЭ по квантовой физике. */
(() => {
  const fmt = x => String(Number(x.toFixed(5))).replace('.', ',');
  const variants = [
    ['Энергия фотона по частоте','10⁻¹⁹ Дж',n=>[
      `Частота света равна ${n}·10¹⁴ Гц. Найди энергию фотона в единицах 10⁻¹⁹ Дж. Прими h = 6,6·10⁻³⁴ Дж·с.`,.66*n,
      'Энергия фотона равна hν.',
      `E = 6,6·${n}·10⁻²⁰ Дж = ${fmt(.66*n)}·10⁻¹⁹ Дж.`]],
    ['Энергия фотона по длине волны','эВ',n=>[
      `Длина волны ультрафиолетового света в вакууме равна ${20*n} нм. Найди энергию фотона в эВ. Используй hc ≈ 1240 эВ·нм.`,62/n,
      'Подставь ν = c/λ в формулу E = hν.',
      `E = 1240/${20*n} эВ ≈ ${fmt(62/n)} эВ.`]],
    ['Импульс фотона','10⁻²⁷ кг·м/с',n=>[
      `Длина волны света в вакууме равна ${40*n} нм. Найди импульс фотона в единицах 10⁻²⁷ кг·м/с. Прими h = 6,6·10⁻³⁴ Дж·с.`,16.5/n,
      'Используй p = h/λ и переведи длину волны в метры.',
      `p = 6,6·10⁻³⁴/(${40*n}·10⁻⁹) кг·м/с ≈ ${fmt(16.5/n)}·10⁻²⁷ кг·м/с.`]],
    ['Количество фотонов в импульсе','10¹²',n=>[
      `Световой импульс несёт ${4*n} мкДж энергии. Энергия одного фотона равна 4·10⁻¹⁹ Дж. Найди число фотонов в единицах 10¹².`,10*n,
      'Раздели энергию импульса на энергию одного фотона.',
      `N = ${4*n}·10⁻⁶/(4·10⁻¹⁹) = ${10*n}·10¹².`]],
    ['Кинетическая энергия фотоэлектрона','эВ',n=>[
      `Катод с работой выхода 2,1 эВ освещают фотонами с энергией ${fmt(2.1+n/4)} эВ. Найди максимальную кинетическую энергию фотоэлектронов в эВ.`,n/4,
      'По уравнению Эйнштейна энергия фотона расходуется на работу выхода и кинетическую энергию.',
      `Kₘₐₓ = ${fmt(2.1+n/4)} − 2,1 = ${fmt(n/4)} эВ.`]],
    ['Работа выхода по задерживающему напряжению','эВ',n=>[
      `Фотон с энергией ${fmt(3+n/5)} эВ вызывает фотоэффект. Модуль задерживающего напряжения равен ${fmt(n/10)} В. Найди работу выхода в эВ.`,3+n/10,
      'При задерживающем напряжении максимальная кинетическая энергия равна eU.',
      `В электронвольтах Kₘₐₓ = ${fmt(n/10)} эВ. Работа выхода A = E − Kₘₐₓ = ${fmt(3+n/10)} эВ.`]],
    ['Красная граница фотоэффекта','нм',n=>[
      `Работа выхода для фотокатода равна ${fmt(2+n/10)} эВ. Найди наибольшую длину волны в вакууме, при которой ещё возможен фотоэффект. Используй hc ≈ 1240 эВ·нм. Ответ дай в нм.`,1240/(2+n/10),
      'На пороге фотоэффекта энергия фотона равна работе выхода.',
      `λₘₐₓ = hc/A = 1240/${fmt(2+n/10)} нм ≈ ${fmt(1240/(2+n/10))} нм.`]],
    ['Изменение задерживающего напряжения','В',n=>[
      `При освещении одного и того же фотокатода частоту увеличили на ${n}·10¹³ Гц. Фотоэффект наблюдается в обоих случаях. На сколько вольт вырос модуль задерживающего напряжения? Прими h = 6,6·10⁻³⁴ Дж·с, e = 1,6·10⁻¹⁹ Кл.`,.04125*n,
      'В разности уравнений Эйнштейна работа выхода сокращается: eΔU = hΔν.',
      `ΔU = 6,6·10⁻³⁴·${n}·10¹³/(1,6·10⁻¹⁹) = ${fmt(.04125*n)} В.`]],
    ['Излучение при переходе между уровнями','нм',n=>[
      `Атом переходит из состояния с энергией −1 эВ в состояние с энергией −${fmt(2+n/5)} эВ. Какова длина волны испущенного фотона в вакууме в нм? Используй hc ≈ 1240 эВ·нм.`,1240/(1+n/5),
      'Энергия испущенного фотона равна разности начальной и конечной энергий атома.',
      `E = −1 − (−${fmt(2+n/5)}) = ${fmt(1+n/5)} эВ. Тогда λ = hc/E ≈ ${fmt(1240/(1+n/5))} нм.`]],
    ['Ионизация из возбуждённого состояния','эВ',n=>[
      `В условной модели атом находится на уровне с энергией −${fmt(1+n/5)} эВ. Ноль энергии соответствует свободному покоящемуся электрону. Атом поглощает фотон с энергией ${fmt(2+n/2)} эВ и ионизируется. Найди кинетическую энергию электрона в эВ, пренебрегая отдачей.`,1+.3*n,
      'Часть энергии фотона тратится на перевод электрона с отрицательного уровня на нулевой.',
      `K = ${fmt(2+n/2)} − ${fmt(1+n/5)} = ${fmt(1+.3*n)} эВ.`]],
    ['Длина волны де Бройля','пм',n=>[
      `Импульс электрона равен ${n}·10⁻²⁴ кг·м/с. Найди длину волны де Бройля в пикометрах. Прими h = 6,6·10⁻³⁴ Дж·с.`,660/n,
      'Длина волны де Бройля равна h/p. Один пикометр равен 10⁻¹² м.',
      `λ = 6,6·10⁻³⁴/(${n}·10⁻²⁴) м ≈ ${fmt(660/n)} пм.`]]
  ];

  for (const [index, [title, unit, build]] of variants.entries()) {
    for (let variant = 1; variant <= 15; variant++) {
      const [question, rawAnswer, plan, calculation] = build(variant + 1);
      const steps = [plan, calculation];
      tasks.push({
        id: `ege-physics-quantum-${index + 1}-${variant}`,
        grade: 11,
        domain: 'physics',
        subject: 'physics',
        exam: 'ege',
        topic: 0,
        topicName: 'Квантовая физика',
        examTopic: 'physics-ege-quantum',
        level: index < 4 ? 0 : index < 8 ? 1 : 2,
        title, question, unit, steps,
        answer: Number(rawAnswer.toFixed(5)),
        hints: [plan],
        solution: steps.join(' '),
        review: {plan},
        source: {
          name: 'Решу ЕГЭ',
          id: 'Квантовая физика',
          type: 'тематический каталог',
          url: 'https://phys-ege.sdamgia.ru/test?category_id=373&filter=all',
          note: 'Авторская задача МатКлуба. Ссылка ведёт на дополнительную практику по фотоэффекту.'
        }
      });
    }
  }
})();

